import os
import base64
from dataclasses import dataclass
from typing import Dict, Optional, Union

from cryptography.hazmat.primitives.ciphers.aead import AESGCM
import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeCiphertext:
    kms_encrypted_data_key: bytes
    nonce: bytes
    ciphertext: bytes
    aad: Optional[bytes] = None

    def serialize(self) -> Dict[str, str]:
        payload = {
            "kms_encrypted_data_key": base64.b64encode(self.kms_encrypted_data_key).decode("utf-8"),
            "nonce": base64.b64encode(self.nonce).decode("utf-8"),
            "ciphertext": base64.b64encode(self.ciphertext).decode("utf-8"),
        }
        if self.aad is not None:
            payload["aad"] = base64.b64encode(self.aad).decode("utf-8")
        return payload

    @classmethod
    def deserialize(cls, payload: Dict[str, str]) -> "EnvelopeCiphertext":
        aad_b = payload.get("aad")
        return cls(
            kms_encrypted_data_key=base64.b64decode(payload["kms_encrypted_data_key"]),
            nonce=base64.b64decode(payload["nonce"]),
            ciphertext=base64.b64decode(payload["ciphertext"]),
            aad=base64.b64decode(aad_b) if aad_b is not None else None,
        )


class AWSEnvelopeEncryptor:
    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name)

    def encrypt(self, plaintext: Union[str, bytes], aad: Optional[Union[str, bytes]] = None) -> EnvelopeCiphertext:
        if isinstance(plaintext, str):
            plaintext = plaintext.encode("utf-8")
        aad_bytes = None
        if aad is not None:
            aad_bytes = aad.encode("utf-8") if isinstance(aad, str) else aad

        try:
            resp = self.kms.generate_data_key(KeyId=self.kms_key_id, KeySpec="AES_256")
            data_key_plaintext = resp["Plaintext"]
            data_key_ciphertext = resp["CiphertextBlob"]
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS generate_data_key failed: {e}") from e

        try:
            aesgcm = AESGCM(data_key_plaintext)
            nonce = os.urandom(12)
            ciphertext = aesgcm.encrypt(nonce, plaintext, aad_bytes)
            return EnvelopeCiphertext(
                kms_encrypted_data_key=data_key_ciphertext,
                nonce=nonce,
                ciphertext=ciphertext,
                aad=aad_bytes,
            )
        finally:
            if isinstance(data_key_plaintext, bytearray):
                for i in range(len(data_key_plaintext)):
                    data_key_plaintext[i] = 0

    def decrypt(self, envelope: Union[EnvelopeCiphertext, Dict[str, str]], aad: Optional[Union[str, bytes]] = None) -> bytes:
        if isinstance(envelope, dict):
            envelope = EnvelopeCiphertext.deserialize(envelope)

        aad_bytes = envelope.aad
        if aad is not None:
            aad_bytes = aad.encode("utf-8") if isinstance(aad, str) else aad

        try:
            resp = self.kms.decrypt(CiphertextBlob=envelope.kms_encrypted_data_key)
            data_key_plaintext = resp["Plaintext"]
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS decrypt failed: {e}") from e

        try:
            aesgcm = AESGCM(data_key_plaintext)
            return aesgcm.decrypt(envelope.nonce, envelope.ciphertext, aad_bytes)
        finally:
            if isinstance(data_key_plaintext, bytearray):
                for i in range(len(data_key_plaintext)):
                    data_key_plaintext[i] = 0

    def encrypt_to_dict(self, plaintext: Union[str, bytes], aad: Optional[Union[str, bytes]] = None) -> Dict[str, str]:
        return self.encrypt(plaintext, aad=aad).serialize()

    def decrypt_from_dict(self, payload: Dict[str, str], aad: Optional[Union[str, bytes]] = None) -> bytes:
        return self.decrypt(payload, aad=aad)
